package com.example.onlineshop.catalog.api;
import com.example.onlineshop.catalog.application.ProductNotFoundException; import com.example.onlineshop.catalog.domain.ProductValidationException; import jakarta.servlet.http.HttpServletRequest; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
@RestControllerAdvice class CatalogExceptionHandler {
 @ExceptionHandler({HttpMessageNotReadableException.class,MethodArgumentTypeMismatchException.class}) ResponseEntity<ProblemDetail> malformed(Exception e,HttpServletRequest r){return problem(400,"MALFORMED_REQUEST","Malformed request","Request could not be parsed",r,List.of());}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ProblemDetail> invalid(MethodArgumentNotValidException e,HttpServletRequest r){var violations=e.getBindingResult().getFieldErrors().stream().map(x->Map.of("field",x.getField(),"message",Objects.toString(x.getDefaultMessage(),"invalid"))).toList();return problem(422,"INVALID_PRODUCT","Validation failed","Product validation failed",r,violations);}
 @ExceptionHandler(ProductValidationException.class) ResponseEntity<ProblemDetail> invalid(ProductValidationException e,HttpServletRequest r){return problem(422,"INVALID_PRODUCT","Validation failed",e.getMessage(),r,List.of(Map.of("field","request","message",e.getMessage())));}
 @ExceptionHandler(ProductNotFoundException.class) ResponseEntity<ProblemDetail> missing(Exception e,HttpServletRequest r){return problem(404,"PRODUCT_NOT_FOUND","Product not found","Product was not found",r,List.of());}
 private ResponseEntity<ProblemDetail> problem(int status,String code,String title,String detail,HttpServletRequest request,List<?> violations){var p=ProblemDetail.forStatusAndDetail(HttpStatus.valueOf(status),detail);p.setTitle(title);p.setType(URI.create("https://github.com/exedeehuashan/online-shop/blob/main/docs/problem-details.md#"+code.toLowerCase().replace('_','-')));p.setInstance(URI.create(request.getRequestURI()));p.setProperty("code",code);p.setProperty("violations",violations);p.setProperty("correlationId",request.getHeader("X-Correlation-ID"));return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}
}
